const { PrismaClient } = require("@prisma/client");
const { Client } = require("ssh2");
const { createDecipheriv, scryptSync } = require("node:crypto");

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error("AUTH_SECRET unset");
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [iv, tag, data] = enc.split(":");
    if (!iv || !tag || !data) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(iv, "base64"));
    d.setAuthTag(Buffer.from(tag, "base64"));
    return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const cmd = process.argv[2];
